/** RANGES as a regular expression's character class, for the `u` flag. */
export const UNASSIGNED_CLASS = `[${RANGES.trim()
  .split(/\s+/)
  .map((range) => {
    const [first, count = "0"] = range.split("-");
    const from = parseInt(first, 36);
    return `\\u{${from.toString(16)}}-\\u{${(from + parseInt(count, 36)).toString(16)}}`;
  })
  .join("")}]`;
